// Captura el texto generado por el nodo de Gemini (Message a model)
const aiResponse = $json?.content?.parts?.[0]?.text || $json?.text || $('Construir Prompt Enriquecido (RAG)').first().json.promptRAG;
const prevData = $('Construir Prompt Enriquecido (RAG)').first().json;

// Genera una marca de tiempo única (Ejemplo: 2026-11-19_03-15-00)
const now = new Date();
const timeStamp = now.toISOString().split('.')[0].replace('T', '_').replace(/:/g, '-');

return [{
  json: {
    ...prevData,
    reportFileName: `informe_rag_rendimiento_${timeStamp}.md`,
    reportContent: aiResponse
  }
}];

const metrics = $('Obtener Métricas Prometheus').first().json?.data?.result || [];
const runbooks = $('Recuperar Contexto RAG (Runbooks)1').all().map(item => item.json);

let downServices = [];
let upServices = [];

metrics.forEach(m => {
  const job = m.metric.job || 'desconocido';
  const instance = m.metric.instance || 'desconocida';
  if (m.value[1] === '1') {
    upServices.push(`${job} (${instance})`);
  } else {
    downServices.push(`${job} (${instance})`);
  }
});

const total = upServices.length + downServices.length;
const ratio = total > 0 ? ((upServices.length / total) * 100).toFixed(1) : '0';

let relevantContext = '';
if (downServices.length > 0) {
  relevantContext = runbooks.filter(r => r.service_name === 'prometheus' || r.issue_type === 'target_down')
                             .map(r => r.content).join('\n');
} else {
  relevantContext = 'Todos los servicios operan con normalidad. Seguir pautas estándar de mantenimiento.';
}

const promptRAG = `Eres un Ingeniero DevOps Sr. Genera un reporte técnico de infraestructura en formato Markdown para el equipo de operaciones.

DATOS EN TIEMPO REAL DEL CLÚSTER:
- Disponibilidad actual: ${ratio}%
- Servicios Activos (UP): ${upServices.join(', ')}
- Servicios Caídos (DOWN): ${downServices.length > 0 ? downServices.join(', ') : 'Ninguno'}

MANUALES Y PROCEDIMIENTOS OPERATIVOS RECUPERADOS (RAG):
${relevantContext}

REQUISITOS DEL INFORME:
1. Resumen Ejecutivo claro y conciso.
2. Evaluación Diagnóstica de los servicios.
3. Recomendaciones y Plan de Acción basado strictly en los procedimientos del RAG brindados.
4. Responde de forma concisa en menos de 300 palabras.`;

const dateStr = new Date().toISOString().split('T')[0];

return [{
  json: {
    reportFileName: `informe_rag_rendimiento_${dateStr}.md`,
    promptRAG: promptRAG,
    healthRatio: `${ratio}%`,
    status: downServices.length === 0 ? 'SUCCESS' : 'WARNING',
    alertname: 'RAG_Performance_Report',
    severity: downServices.length === 0 ? 'info' : 'warning'
  }
}];
